window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e40b7299102df939"]={"versions": [{"id": "FIG-e40b7299102df939", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Struktur für die Spezifikation von Softwarekomponenten (AUTOSAR_SoftwareComponentTemplate). Es modelliert die Anbindung der Anforderungen einer Software-Komponente an die Überwachung durch den Watchdog-Manager (Watchdog Service) über Service-Needs und Port-Zuweisungen innerhalb des internen Verhaltens (<code>InternalBehavior</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwcInternalBehavior::InternalBehavior</code> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ supportsMultipleInstantiation: Boolean</code>\n</li><li>Aggregation zu <code>Identifiable / ServiceNeeds::ServiceNeeds</code> über die Rolle <code>+serviceNeeds</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>ServiceNeeds::ServiceNeeds</code> (Spezialisierung von <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Basisklasse für servicebezogene Anforderungen.\n</li></ul>\n</li><li><code>ServiceNeeds::SupervisedEntityNeeds</code>:\n<ul class=\"fig-list\"><li>Generalisierung / Spezialisierung von <code>ServiceNeeds::ServiceNeeds</code>.\n</li><li>Attribute zur Parametrierung der Watchdog-Überwachung:\n<ul class=\"fig-list\"><li><code>+ activateAtStart: Boolean</code>\n</li><li><code>+ enableDeactivation: Boolean</code>\n</li><li><code>+ expectedAliveCycle: Float</code>\n</li><li><code>+ maxAliveCycle: Float</code>\n</li><li><code>+ minAliveCycle: Float</code>\n</li><li><code>+ toleratedFailedCycles: Int</code>\n</li></ul>\n</li></ul>\n</li><li><code>SwcSupervisedEntityNeeds</code>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ServiceNeeds::SupervisedEntityNeeds</code>.\n</li><li>Aggregation zu <code>RoleBasedRPortAssignment</code> über die Rolle <code>+serviceCallPort</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>RoleBasedRPortAssignment</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ role: Identifier</code>\n</li><li>Unidirektionale Assoziation zu <code>Components::RPortPrototype</code> über die Rolle <code>+rPortPrototype</code> mit Multiplizität <code>1</code>.\n</li></ul>\n</li><li><code>Components::RPortPrototype</code> (Stereotyp <code>«atpPrototype»</code>, Spezialisierung von <code>PortPrototype</code>):\n<ul class=\"fig-list\"><li>Empfangsport-Prototyp zur Interaktion mit dem Watchdog-Service.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur; es wird kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Die modellierten Attribute und Assoziationen legen die Konfigurationsparameter fest, anhand derer zur Laufzeit die Alive-Supervision einer Supervised Entity (SE) durch den Watchdog-Manager initiiert, überwacht und über den zugeordneten <code>RPortPrototype</code> bedient wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für AUTOSAR-Autoren und Generatoren im Rahmen der SWC-Beschreibung:</p>\n<ul class=\"fig-list\"><li>Eine Software-Komponente mit internem Verhalten kann mehrere <code>ServiceNeeds</code> deklarieren.\n</li><li>Für jede überwachte Entität (Supervised Entity) wird über <code>SwcSupervisedEntityNeeds</code> definiert, welche Zyklenanforderungen (<code>minAliveCycle</code>, <code>maxAliveCycle</code>, <code>expectedAliveCycle</code>, <code>toleratedFailedCycles</code>) gelten und ob die Überwachung beim Start aktiv ist (<code>activateAtStart</code>).\n</li><li>Über <code>RoleBasedRPortAssignment</code> muss genau ein <code>RPortPrototype</code> (<code>1</code>) mit einer spezifischen Rolle (<code>role: Identifier</code>) angebunden werden, über den der Serviceaufruf an den Watchdog-Manager erfolgt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-509c4a00a76e0bae", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Struktur für die Spezifikation von Softwarekomponenten (AUTOSAR_SoftwareComponentTemplate). Es modelliert die Anbindung der Anforderungen einer Software-Komponente an die Überwachung durch den Watchdog-Manager (Watchdog Service) über Service-Needs und Port-Zuweisungen innerhalb des internen Verhaltens (<code>InternalBehavior</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwcInternalBehavior::InternalBehavior</code> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ supportsMultipleInstantiation: Boolean</code>\n</li><li>Aggregation zu <code>Identifiable / ServiceNeeds::ServiceNeeds</code> über die Rolle <code>+serviceNeeds</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>ServiceNeeds::ServiceNeeds</code> (Spezialisierung von <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Basisklasse für servicebezogene Anforderungen.\n</li></ul>\n</li><li><code>ServiceNeeds::SupervisedEntityNeeds</code>:\n<ul class=\"fig-list\"><li>Generalisierung / Spezialisierung von <code>ServiceNeeds::ServiceNeeds</code>.\n</li><li>Attribute zur Parametrierung der Watchdog-Überwachung:\n<ul class=\"fig-list\"><li><code>+ activateAtStart: Boolean</code>\n</li><li><code>+ enableDeactivation: Boolean</code>\n</li><li><code>+ expectedAliveCycle: Float</code>\n</li><li><code>+ maxAliveCycle: Float</code>\n</li><li><code>+ minAliveCycle: Float</code>\n</li><li><code>+ toleratedFailedCycles: Int</code>\n</li></ul>\n</li></ul>\n</li><li><code>SwcSupervisedEntityNeeds</code>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ServiceNeeds::SupervisedEntityNeeds</code>.\n</li><li>Aggregation zu <code>RoleBasedRPortAssignment</code> über die Rolle <code>+serviceCallPort</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>RoleBasedRPortAssignment</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ role: Identifier</code>\n</li><li>Unidirektionale Assoziation zu <code>Components::RPortPrototype</code> über die Rolle <code>+rPortPrototype</code> mit Multiplizität <code>1</code>.\n</li></ul>\n</li><li><code>Components::RPortPrototype</code> (Stereotyp <code>«atpPrototype»</code>, Spezialisierung von <code>PortPrototype</code>):\n<ul class=\"fig-list\"><li>Empfangsport-Prototyp zur Interaktion mit dem Watchdog-Service.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur; es wird kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Die modellierten Attribute und Assoziationen legen die Konfigurationsparameter fest, anhand derer zur Laufzeit die Alive-Supervision einer Supervised Entity (SE) durch den Watchdog-Manager initiiert, überwacht und über den zugeordneten <code>RPortPrototype</code> bedient wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für AUTOSAR-Autoren und Generatoren im Rahmen der SWC-Beschreibung:</p>\n<ul class=\"fig-list\"><li>Eine Software-Komponente mit internem Verhalten kann mehrere <code>ServiceNeeds</code> deklarieren.\n</li><li>Für jede überwachte Entität (Supervised Entity) wird über <code>SwcSupervisedEntityNeeds</code> definiert, welche Zyklenanforderungen (<code>minAliveCycle</code>, <code>maxAliveCycle</code>, <code>expectedAliveCycle</code>, <code>toleratedFailedCycles</code>) gelten und ob die Überwachung beim Start aktiv ist (<code>activateAtStart</code>).\n</li><li>Über <code>RoleBasedRPortAssignment</code> muss genau ein <code>RPortPrototype</code> (<code>1</code>) mit einer spezifischen Rolle (<code>role: Identifier</code>) angebunden werden, über den der Serviceaufruf an den Watchdog-Manager erfolgt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-14e6c7a5257ba3cd", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodell-Struktur für die Spezifikation von Softwarekomponenten (AUTOSAR_SoftwareComponentTemplate). Es modelliert die Anbindung der Anforderungen einer Software-Komponente an die Überwachung durch den Watchdog-Manager (Watchdog Service) über Service-Needs und Port-Zuweisungen innerhalb des internen Verhaltens (<code>InternalBehavior</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Metaklassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>SwcInternalBehavior::InternalBehavior</code> (Spezialisierung von <code>ARElement</code>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ supportsMultipleInstantiation :Boolean</code>\n</li><li>Aggregation zu <code>Identifiable / ServiceNeeds::ServiceNeeds</code> über die Rolle <code>+serviceNeeds</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>ServiceNeeds::ServiceNeeds</code> (Spezialisierung von <code>Identifiable</code>):\n<ul class=\"fig-list\"><li>Basisklasse für servicebezogene Anforderungen.\n</li></ul>\n</li><li><code>ServiceNeeds::SupervisedEntityNeeds</code>:\n<ul class=\"fig-list\"><li>Generalisierung / Spezialisierung von <code>ServiceNeeds::ServiceNeeds</code>.\n</li><li>Attribute zur Parametrierung der Watchdog-Überwachung:\n<ul class=\"fig-list\"><li><code>+ activateAtStart :Boolean</code>\n</li><li><code>+ enableDeactivation :Boolean</code>\n</li><li><code>+ expectedAliveCycle :Float</code>\n</li><li><code>+ maxAliveCycle :Float</code>\n</li><li><code>+ minAliveCycle :Float</code>\n</li><li><code>+ toleratedFailedCycles :Integer</code>\n</li></ul>\n</li></ul>\n</li><li><code>SwcSupervisedEntityNeeds</code>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>ServiceNeeds::SupervisedEntityNeeds</code>.\n</li><li>Aggregation zu <code>RoleBasedRPortAssignment</code> über die Rolle <code>+serviceCallPort</code> mit Multiplizität <code>0..*</code>.\n</li></ul>\n</li><li><code>RoleBasedRPortAssignment</code>:\n<ul class=\"fig-list\"><li>Attribut: <code>+ role :Identifier</code>\n</li><li>Unidirektionale Assoziation zu <code>Components::RPortPrototype</code> über die Rolle <code>+rPortPrototype</code> mit Multiplizität <code>1</code>.\n</li></ul>\n</li><li><code>Components::RPortPrototype</code> (Stereotyp <code>«atpPrototype»</code>, Spezialisierung von <code>PortPrototype</code>):\n<ul class=\"fig-list\"><li>Empfangsport-Prototyp zur Interaktion mit dem Watchdog-Service.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Metamodell-Struktur; es wird kein dynamischer Laufzeit- oder Sequenzablauf dargestellt. Die modellierten Attribute und Assoziationen legen die Konfigurationsparameter fest, anhand derer zur Laufzeit die Alive-Supervision einer Supervised Entity (SE) durch den Watchdog-Manager initiiert, überwacht und über den zugeordneten <code>RPortPrototype</code> bedient wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für AUTOSAR-Autoren und Generatoren im Rahmen der SWC-Beschreibung:</p>\n<ul class=\"fig-list\"><li>Eine Software-Komponente mit internem Verhalten kann mehrere <code>ServiceNeeds</code> deklarieren.\n</li><li>Für jede überwachte Entität (Supervised Entity) wird über <code>SwcSupervisedEntityNeeds</code> definiert, welche Zyklenanforderungen (<code>minAliveCycle</code>, <code>maxAliveCycle</code>, <code>expectedAliveCycle</code>, <code>toleratedFailedCycles</code>) gelten und ob die Überwachung beim Start aktiv ist (<code>activateAtStart</code>).\n</li><li>Über <code>RoleBasedRPortAssignment</code> muss genau ein <code>RPortPrototype</code> (<code>1</code>) mit einer spezifischen Rolle (<code>role: Identifier</code>) angebunden werden, über den der Serviceaufruf an den Watchdog-Manager erfolgt.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e40b7299102df939", "to": "FIG-509c4a00a76e0bae", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-509c4a00a76e0bae", "to": "FIG-14e6c7a5257ba3cd", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>toleratedFailedCycles</code> in Metaklasse <code>SupervisedEntityNeeds</code>: Datentyp von <code>Int</code> auf <code>Integer</code> geändert.\n</li><li>Vereinheitlichung der Syntax-Typnotation mit vorangestelltem Doppelpunkt ohne Leerzeichen vor dem Typnamen in Attributen (<code>:Boolean</code>, <code>:Float</code>, <code>:Integer</code>, <code>:Identifier</code>).\n</li></ul>"}]};
